qAttributeExpressions.qExpression:
If(GetSelectedCount([Primary Function]) > 0, 
    If( Avg({$< Outlier = {'0'} >} [EUI (kBtu/SqFt)]) <= Avg([Site EUI]), Green(),
    If( Avg({$< Outlier = {'0'} >} [EUI (kBtu/SqFt)]) <= (1.05 * Avg([Site EUI])), Yellow(),
    If( Avg({$< Outlier = {'0'} >} [EUI (kBtu/SqFt)]) > (1.05 * Avg([Site EUI])), Red()
    )
    )
    )
,
	Blue()
)

